(() => {
'use strict';
const canvas=document.querySelector('#game'),ctx=canvas.getContext('2d',{alpha:false}),W=480,H=270;
ctx.imageSmoothingEnabled=false;
const worlds=[
 {name:'THE LOST TEA FOREST',short:'TEA FOREST',boss:'THE ANCIENT BLOOM',desc:'Where the old roots remember.',sky:['#223943','#769269'],far:'#41645a',mid:'#31534c',ground:'#303c32',top:'#81935a',accent:'#eabf67',mood:'forest',unlocked:true},
 {name:'THE CANDY KINGDOM',short:'CANDY KINGDOM',boss:'DUKE NOUGAT',desc:'Sweetness with a bitter core.',sky:['#613747','#df926f'],far:'#a66073',mid:'#7b455b',ground:'#63404b',top:'#e69587',accent:'#ffd579',mood:'candy'},
 {name:'THE SUNKEN KETTLE',short:'SUNKEN KETTLE',boss:'THE DROWNED ADMIRAL',desc:'A kingdom beneath the boil.',sky:['#122f45','#42828a'],far:'#286579',mid:'#17475a',ground:'#243d48',top:'#64b5aa',accent:'#b5eddb',mood:'deep'},
 {name:'THE IRON TEA WORKS',short:'IRON TEA WORKS',boss:'THE BRASS REGENT',desc:'Every cog has a hungry tooth.',sky:['#382b35','#b9694e'],far:'#70453e',mid:'#553637',ground:'#393335',top:'#a87c55',accent:'#f2ad61',mood:'forge'},
 {name:'THE SUGAR CROWN',short:'SUGAR CROWN',boss:'THE CARAMEL KING',desc:'The last cup is served.',sky:['#1b2438','#78647a'],far:'#51465d',mid:'#373749',ground:'#34313b',top:'#a29a8c',accent:'#f5d477',mood:'crown'}
];
const weapons=[
 {name:'TEA BLASTER',icon:'✦',dmg:1,rate:20,speed:5,color:'#ffe29a',kind:'tea',unlock:0},
 {name:'SCATTERSHOT',icon:'✹',dmg:1,rate:37,speed:4,color:'#ff9c6e',kind:'spread',unlock:0},
 {name:'ARC LANCER',icon:'ϟ',dmg:1,rate:29,speed:6,color:'#8de8eb',kind:'electric',unlock:1},
 {name:'EMBER CANNON',icon:'♨',dmg:2,rate:46,speed:4,color:'#ff734b',kind:'fire',unlock:2},
 {name:'BUBBLE SEEKER',icon:'○',dmg:1,rate:32,speed:3,color:'#a6e7dc',kind:'homing',unlock:3},
 {name:'BIG BANG',icon:'✹',dmg:3,rate:60,speed:3,color:'#f7ce67',kind:'bomb',unlock:4}
];
const enemyKinds=[
 ['Tea mite','walker',2,1,'#e5bd79'],['Gear gnat','fly',2,1,'#95c9a8'],['Kettle guard','guard',5,1,'#96a5a0'],['Pop-rock','explode',1,2,'#ee8791'],['Pinpoint','sniper',3,1,'#b8a5d6'],['Hop goblin','jumper',3,1,'#d58f6e'],['Cup wraith','ghost',3,1,'#9ccfce'],['Saucer shield','shield',4,1,'#cfb26e'],['Mosscap brute','brute',7,2,'#adbd70'],['Fizz drone','drone',2,2,'#eb9b89'],['Cog crawler','crawler',4,1,'#99a5a0'],['Sour spitter','spitter',4,1,'#8dc77a'],['Iron pourer','heavy',8,2,'#889699'],['Brewling elite','elite',6,2,'#e48264'],['Royal tea knight','knight',9,2,'#d8bd76']
].map((e,i)=>({name:e[0],ai:e[1],hp:e[2],dmg:e[3],color:e[4],id:i}));
const el=id=>document.getElementById(id),screens=[...document.querySelectorAll('.screen')],hud=el('hud');
let state='title',selectedWorld=0,world=worlds[0],unlocked=1,sceneTime=0,last=0,keys={},touch={},player,foes=[],shots=[],enemyShots=[],particles=[],drops=[],camera=0,worldX=0,score=0,kills=0,weaponIndex=0,fireCooldown=0,spawned=0,boss=null,bossActive=false,shake=0,tipTimer=0,previewCanvases=[],soundOn=true,audio;
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v)),rand=(a,b)=>a+Math.random()*(b-a),irand=n=>Math.floor(Math.random()*n);
function showScreen(name){screens.forEach(s=>s.classList.toggle('visible',s.id===name));hud.classList.toggle('hidden',!['playing','paused'].includes(state));}
function startWorld(i){selectedWorld=i;world=worlds[i];state='playing';showScreen('');worldX=40;camera=0;score=0;kills=0;spawned=0;shots=[];enemyShots=[];foes=[];particles=[];drops=[];boss=null;bossActive=false;fireCooldown=0;weaponIndex=Math.min(i,weapons.length-1);player={x:worldX,y:206,vx:0,vy:0,w:17,h:22,face:1,hp:5,maxHp:5,steam:0,jumps:0,onGround:false,invuln:0,dash:0,dashCd:0,parry:0,anim:'idle',animT:0,shot:0,ult:0};el('hud-world').textContent=world.name;el('boss-bar').classList.add('hidden');el('game-tip').textContent=i===0?'JUMP TWICE TO REACH THE HIGH PATH':'FIND THE RELIC. KEEP YOUR KETTLE UP.';tipTimer=260;updateHud();beep(540,.07,'triangle');}
function goTitle(){state='title';showScreen('title-screen')}
function openWorlds(){state='worlds';showScreen('world-screen');buildWorldCards()}
function unlockWorld(i){unlocked=Math.max(unlocked,Math.min(worlds.length,i+1));worlds.slice(0,unlocked).forEach(w=>w.unlocked=true)}
function buildWorldCards(){const list=el('world-list');list.innerHTML='';worlds.forEach((w,i)=>{const b=document.createElement('button');b.className='world-card';b.disabled=i>=unlocked;b.innerHTML=`<canvas width="150" height="150"></canvas><span class="world-number">${String(i+1).padStart(2,'0')}</span><span class="world-card-copy"><b>${w.name}</b><small>${i<unlocked?'BOSS · '+w.boss:'LOCKED · FIND THE RELICS'}</small></span>`;b.onclick=()=>i<unlocked&&startWorld(i);list.appendChild(b);drawPreview(b.querySelector('canvas'),w,i);});}
function drawPreview(c,w,i){const g=c.getContext('2d');g.imageSmoothingEnabled=false;let gr=g.createLinearGradient(0,0,0,150);gr.addColorStop(0,w.sky[0]);gr.addColorStop(1,w.sky[1]);g.fillStyle=gr;g.fillRect(0,0,150,150);g.fillStyle=w.far;for(let x=0;x<180;x+=25){g.fillRect(x,50+irand(18),14,70);g.fillRect(x-8,78,30,18)}g.fillStyle=w.mid;for(let x=0;x<180;x+=33){g.fillRect(x,88,21,39);g.fillRect(x-8,108,38,12)}g.fillStyle=w.ground;g.fillRect(0,120,150,30);g.fillStyle=w.top;g.fillRect(0,118,150,4);g.fillStyle=w.accent;g.fillRect(103,46,16,19);g.fillRect(99,50,24,11);g.fillStyle='#ffdc78';g.fillRect(108,51,3,3);g.fillStyle='#263a37';g.fillRect(43,94,15,23);g.fillStyle='#e2d2ae';g.fillRect(45,88,12,10);g.fillStyle='#394746';g.fillRect(42,91,16,6);g.fillStyle='#f0c85e';g.fillRect(47,93,3,3);g.fillRect(53,93,3,3);}
function updateHud(){if(!player)return;el('hp-text').textContent=`${player.hp} / ${player.maxHp}`;el('health-fill').style.width=`${100*player.hp/player.maxHp}%`;el('steam-text').textContent=`${Math.floor(player.steam)}%`;el('steam-fill').style.width=`${player.steam}%`;const w=weapons[weaponIndex];el('weapon-name').textContent=w.name;el('weapon-icon').textContent=w.icon;}
function beep(freq=440,dur=.06,type='square',vol=.025){if(!soundOn)return;try{audio=audio||new(window.AudioContext||window.webkitAudioContext)();const o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(vol,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+dur);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+dur)}catch(_){}}
function inputDown(k){keys[k]=true;if(k==='Escape'||k==='p'){if(state==='playing')pauseGame();else if(state==='paused')resumeGame()}if(state==='playing'){if(k==='q')switchWeapon(-1);if(k==='e')switchWeapon(1);if(k==='k'||k==='x')useSpecial();if(k==='l'||k==='shift')dash();if(k==='j'||k==='z')fire()}}
function inputUp(k){keys[k]=false}
window.addEventListener('keydown',e=>{const k=e.key.toLowerCase();if([' ','arrowleft','arrowright','arrowup','arrowdown'].includes(k))e.preventDefault();if(!keys[k])inputDown(k)});window.addEventListener('keyup',e=>inputUp(e.key.toLowerCase()));
el('play-button').onclick=openWorlds;el('back-title').onclick=goTitle;el('pause-button').onclick=pauseGame;el('resume-button').onclick=resumeGame;el('quit-button').onclick=openWorlds;el('result-button').onclick=()=>{if(selectedWorld<4&&worlds[selectedWorld+1].unlocked)openWorlds();else openWorlds()};
function pauseGame(){if(state!=='playing')return;state='paused';showScreen('pause-screen')}
function resumeGame(){if(state!=='paused')return;state='playing';showScreen('')}
function switchWeapon(dir){const unlockedWeapons=weapons.map((w,i)=>i).filter(i=>weapons[i].unlock<=selectedWorld);weaponIndex=(weaponIndex+dir+unlockedWeapons.length)%unlockedWeapons.length;updateHud();beep(380,.035,'square')}
function dash(){if(!player||player.dashCd>0)return;player.dash=10;player.dashCd=48;player.invuln=Math.max(player.invuln,12);player.vx=player.face*7;player.vy*=.35;player.anim='dash';emit(player.x,player.y,world.accent,7);beep(250,.08,'sawtooth')}
function useSpecial(){if(!player||player.steam<100)return;player.steam=0;player.ult=38;shake=9;shots=shots.filter(s=>s.from!=='enemy');for(const e of foes){e.hp-=7;e.hit=12}if(boss){boss.hp-=18;boss.hit=15}emit(player.x,player.y,'#fff0a5',48);for(let n=0;n<12;n++)emit(player.x+rand(-130,130),player.y+rand(-65,30),'#ffb85b',3);beep(100,.48,'sawtooth',.06);updateHud()}
function fire(){if(!player||fireCooldown>0||player.ult)return;const w=weapons[weaponIndex];fireCooldown=w.rate;player.shot=9;player.anim='shoot';const angle=player.face===1?0:Math.PI;const add=(a,spd=w.speed)=>{shots.push({x:player.x+player.face*12,y:player.y-8,vx:Math.cos(a)*spd,vy:Math.sin(a)*spd,kind:w.kind,dmg:w.dmg,color:w.color,life:100,from:'player',size:w.kind==='bomb'?5:3});};if(w.kind==='spread'){[-.24,0,.24].forEach(a=>add(a*player.face,4.2))}else add(angle);emit(player.x+player.face*11,player.y-8,w.color,3);beep(w.kind==='electric'?760:w.kind==='bomb'?180:510,.05,w.kind==='electric'?'sawtooth':'square')}
function emit(x,y,color,n=5){for(let i=0;i<n;i++)particles.push({x,y,vx:rand(-1.7,1.7),vy:rand(-2.2,.3),life:rand(12,28),max:28,color,size:Math.random()<.25?3:2})}
function damagePlayer(dmg=1){if(player.invuln>0)return;player.hp-=dmg;player.invuln=75;player.vx=-player.face*3;player.vy=-3;shake=5;emit(player.x,player.y-10,'#f77b60',10);beep(110,.15,'sawtooth');updateHud();if(player.hp<=0){setTimeout(()=>endWorld(false),450)}}
function endWorld(win){if(state!=='playing')return;state='result';showScreen('result-screen');el('boss-bar').classList.add('hidden');if(win){unlockWorld(selectedWorld);el('result-eyebrow').textContent='RELIC RECOVERED';el('result-title').textContent='A FINE BREW!';el('result-copy').textContent=`${world.name} can breathe again. ${world.boss} has gone cold.`;el('result-button').textContent=selectedWorld<4?'CHOOSE NEXT WORLD':'RETURN TO THE WILDS';beep(750,.24,'triangle',.04)}else{el('result-eyebrow').textContent='KETTLE'S GONE COLD';el('result-title').textContent='NOT THIS TIME.';el('result-copy').textContent='Every good brew takes a few tries.';el('result-button').textContent='TRY AGAIN';el('result-button').onclick=()=>startWorld(selectedWorld);beep(100,.4,'sawtooth',.045)}el('result-stats').innerHTML=`<span><b>${kills}</b><br>FOES BESTED</span><span><b>${score}</b><br>TEA LEAVES</span><span><b>${Math.floor(player.steam)}%</b><br>STEAM LEFT</span>`;if(win)el('result-button').onclick=()=>{el('result-button').onclick=null;openWorlds()}}
function groundY(x){return 222}
const platformList=[{x:340,y:181,w:84},{x:620,y:161,w:92},{x:870,y:187,w:76},{x:1120,y:169,w:96},{x:1430,y:183,w:78},{x:1700,y:158,w:110},{x:2020,y:183,w:92},{x:2320,y:166,w:110}];
function platAt(x,y,vy){for(const p of platformList){if(x+8>p.x&&x-8<p.x+p.w&&y>=p.y&&y<=p.y+9&&vy>=0)return p}return null}
function spawnEnemy(x,idx){const def=enemyKinds[idx%enemyKinds.length];const y=(['fly','drone'].includes(def.ai))?rand(132,177):groundY(x);foes.push({x,y,baseY:y,hp:def.hp,maxHp:def.hp,def,vx:0,vy:0,dir:Math.random()<.5?-1:1,phase:rand(0,9),attack:rand(30,100),hit:0,dead:0,face:1,shield:100,patrol:rand(35,90)});}
function spawnBoss(){bossActive=true;const names=[['THE ANCIENT BLOOM',40],['DUKE NOUGAT',48],['THE DROWNED ADMIRAL',54],['THE BRASS REGENT',58],['THE CARAMEL KING',64]][selectedWorld];boss={x:2630,y:185,hp:names[1],maxHp:names[1],name:names[0],phase:0,attack:65,hit:0,dir:-1};el('boss-name').textContent=boss.name;el('boss-bar').classList.remove('hidden');beep(90,.32,'sawtooth',.05);}
function worldInput(dt){const left=keys.a||keys.arrowleft||touch.left,right=keys.d||keys.arrowright||touch.right,jump=keys[' ']||keys.arrowup||touch.jump;const was=player.onGround;player.onGround=false;player.animT+=dt;player.invuln=Math.max(0,player.invuln-dt);player.dashCd=Math.max(0,player.dashCd-dt);player.parry=Math.max(0,player.parry-dt);if(player.dash>0){player.dash-=dt;player.vx=player.face*7;player.anim='dash'}else{let ax=(right?1:0)-(left?1:0);if(ax){player.face=ax;player.vx+=ax*.65*dt;player.vx=clamp(player.vx,-2.7,2.7);if(player.onGround)player.anim='run'}else player.vx*=Math.pow(.76,dt);if(Math.abs(player.vx)<.08)player.vx=0}
 if(jump&&!player.jumpHeld&&player.jumps<2){player.vy=player.jumps===0?-6.5:-6.1;player.jumps++;player.onGround=false;player.anim=player.jumps===2?'double':'jump';player.jumpHeld=true;beep(player.jumps===2?660:440,.07,'square');emit(player.x,player.y,world.accent,5)}if(!jump)player.jumpHeld=false;
 if(keys.s||keys.arrowdown||touch.parry){player.parry=6;player.anim='parry'}if(touch.fire||keys.j||keys.z)fire();
 player.x+=player.vx*dt;player.y+=player.vy*dt;player.vy+=.29*dt;
 const floor=groundY(player.x);if(player.y>=floor){if(!was&&player.vy>2){player.anim='land';emit(player.x,player.y,world.top,4)}player.y=floor;player.vy=0;player.jumps=0;player.onGround=true;if(player.anim!=='shoot'&&player.anim!=='dash'&&player.anim!=='parry'&&player.anim!=='land')player.anim=Math.abs(player.vx)>.3?'run':'idle'}
 const p=platAt(player.x,player.y,player.vy);if(p&&player.y<=p.y+6){player.y=p.y;player.vy=0;player.jumps=0;player.onGround=true}
 player.x=clamp(player.x,15,2800);worldX=player.x;camera=clamp(player.x-145,0,2320);player.shot=Math.max(0,player.shot-dt);if(player.shot===0&&player.anim==='shoot')player.anim=player.onGround?(Math.abs(player.vx)>.3?'run':'idle'):(player.vy<0?'jump':'fall');
 if(player.y>H+30)damagePlayer(2);
}

