function update(dt){sceneTime+=dt;if(state!=='playing')return;worldInput(dt);fireCooldown=Math.max(0,fireCooldown-dt);if(player.ult>0)player.ult-=dt;if(tipTimer>0){tipTimer-=dt;el('game-tip').classList.add('show')}else el('game-tip').classList.remove('show');if(player.x>145+spawned*145&&spawned<15){spawnEnemy(player.x+235,spawned+selectedWorld*3);spawned++;}
 if(player.x>2480&&!boss){spawnBoss()}
 for(let i=foes.length-1;i>=0;i--){const e=foes[i],d=e.def;e.phase+=dt*.08;e.attack-=dt;e.hit=Math.max(0,e.hit-dt);if(e.dead){e.dead-=dt;if(e.dead<=0)foes.splice(i,1);continue}if(Math.abs(e.x-player.x)>650)continue;
 switch(d.ai){case'walker':case'guard':case'shield':case'heavy':case'knight':case'elite':case'brute':e.vx=d.ai==='walker'?e.dir*.55:d.ai==='brute'?e.dir*.34:e.dir*.44;if(Math.abs(player.x-e.x)<170)e.dir=Math.sign(player.x-e.x)||1;if(d.ai==='guard'||d.ai==='shield')e.shield=Math.abs(player.x-e.x)<105?1:0;if(d.ai==='knight'&&e.attack<0){e.vx=Math.sign(player.x-e.x)*2.6;e.attack=100}break;
 case'fly':case'drone':e.y=e.baseY+Math.sin(e.phase)*16;e.x+=Math.sign(player.x-e.x)*.42*dt;if(e.attack<0){enemyShots.push({x:e.x,y:e.y,vx:Math.sign(player.x-e.x)*1.6,vy:.3,life:100,kind:'seed',color:d.color});e.attack=100;beep(220,.03,'triangle')}break;
 case'sniper':e.vx=0;if(e.attack<0){let a=Math.atan2(player.y-e.y,player.x-e.x);enemyShots.push({x:e.x,y:e.y-8,vx:Math.cos(a)*2.1,vy:Math.sin(a)*2.1,life:120,kind:'shot',color:'#f59c79'});e.attack=95}break;
