window.addEventListener('keyup',e=>{keys[e.key]=false});
function jump(){if(state!=='playing'||player.jumps>=2)return;player.vy=-6.2;player.jumps++;burst(player.x+9,player.y+21,'#e3ead9',4)}
function resumeGame(){state='playing';showScreen(null)}
document.querySelectorAll('[data-control]').forEach(b=>{const key=b.dataset.control;const down=e=>{e.preventDefault();touch[key]=true;b.classList.add('active');if(key==='jump')jump();if(key==='dash')dash();if(key==='special')useSpecial();if(key==='fire')fire()};const up=e=>{e.preventDefault();touch[key]=false;b.classList.remove('active')};b.addEventListener('pointerdown',down);b.addEventListener('pointerup',up);b.addEventListener('pointercancel',up);b.addEventListener('pointerleave',up)});
canvas.addEventListener('pointerdown',e=>{if(state==='playing'&&e.pointerType==='touch'){const r=canvas.getBoundingClientRect(),x=(e.clientX-r.left)/r.width*W;if(x>W*.45)fire()}});
window.addEventListener('blur',()=>{Object.keys(keys).forEach(k=>keys[k]=false);if(state==='playing')pauseGame()});
showScreen('title-screen');renderWorlds();requestAnimationFrame(frame);
})();

